let currentLang = 'th';
function t(key, ...args){
  const dict = I18N[currentLang] || I18N.en;
  const v = dict[key];
  if(typeof v === 'function') return v(...args);
  return v!==undefined ? v : (I18N.en[key]!==undefined ? (typeof I18N.en[key]==='function'?I18N.en[key](...args):I18N.en[key]) : key);
}
function renderLangSwitch(){
  const html = `<button data-lang="th" class="${currentLang==='th'?'active':''}">TH</button><button data-lang="en" class="${currentLang==='en'?'active':''}">EN</button>`;
  document.getElementById('langSwitchDesktop').innerHTML = html;
  document.getElementById('langSwitchMobile').innerHTML = html;
  document.querySelectorAll('[data-lang]').forEach(el=>el.addEventListener('click', ()=>setLang(el.getAttribute('data-lang'))));
}
async function setLang(lang){
  if(lang===currentLang) return;
  currentLang = lang;
  document.documentElement.lang = lang;
  renderLangSwitch();
  if(profile){
    renderNav();
    navigate(currentView);
    if(canEdit){ profile.language = lang; await sb.from('profiles').update({language:lang}).eq('id', currentUser.id); }
  } else if(!coachMode){
    renderAuthOrOnboarding();
  }
}

