/* ============ INIT / AUTH ============ */
async function init(){
  if(!window.SUPABASE_URL || window.SUPABASE_URL.includes('YOUR_SUPABASE')){
    document.getElementById('main').innerHTML = `<div class="card">${t('connect_error')}</div>`;
    return;
  }
  sb = window.supabase.createClient(window.SUPABASE_URL, window.SUPABASE_ANON_KEY);

  const params = new URLSearchParams(window.location.search);
  const tokenFromUrl = params.get('coach');
  if(tokenFromUrl){
    coachMode = true;
    coachToken = tokenFromUrl;
    canEdit = false;
    await loadCoachReport(tokenFromUrl);
    return;
  }

  const { data:{ session } } = await sb.auth.getSession();
  if(session){
    currentUser = session.user;
    canEdit = true;
    await afterLogin();
  } else {
    renderAuthOrOnboarding();
  }

  sb.auth.onAuthStateChange((event, session)=>{
    if(event==='SIGNED_IN' && !coachMode){
      currentUser = session.user;
      canEdit = true;
      afterLogin();
    } else if(event==='SIGNED_OUT'){
      currentUser=null; profile=null; checkins={};
      renderAuthOrOnboarding();
    }
  });
}

async function afterLogin(){
  document.getElementById('sidebar').style.display='flex';
  await loadProfile();
  if(profile && profile.language) currentLang = profile.language;
  renderLangSwitch();
  await loadAllCheckins();
  renderNav();
  document.getElementById('logoutBtn').textContent = t('logout');
  document.getElementById('logoutBtn').onclick = async ()=>{ await sb.auth.signOut(); };
  if(!profile){ renderOnboarding(); } else { navigate('dashboard'); }
}

async function loadProfile(){
  const { data, error } = await sb.from('profiles').select('*').eq('id', currentUser.id).maybeSingle();
  profile = (!error && data) ? data : null;
}
async function loadAllCheckins(){
  checkins = {};
  const { data, error } = await sb.from('checkins').select('week,data').eq('user_id', currentUser.id);
  if(!error && data) data.forEach(row=>{ checkins[row.week] = row.data; });
}
async function loadCoachReport(token){
  const { data, error } = await sb.rpc('get_coach_report', { p_token: token });
  if(error || !data){
    document.getElementById('main').innerHTML = `<div class="card">${t('connect_error')}</div>`;
    return;
  }
  profile = data.profile;
  checkins = {};
  (data.checkins||[]).forEach(c=>{ checkins[c.week]=c; });
  if(profile && profile.language) currentLang = profile.language;
  renderLangSwitch();
  renderNav();
  navigate('dashboard');
}

