function renderAuthOrOnboarding(){
  document.getElementById('sidebar').style.display='none';
  renderAuthScreen('login');
}
function renderAuthScreen(mode){
  const main = document.getElementById('main');
  if(mode==='forgot'){
    main.innerHTML = `
      <div class="auth-wrap"><div class="card">
        <div class="onboard-header"><img src="${DIAMOND_LOGO}"><h1>DIAMONDMASS</h1><p>${t('auth_forgot')}</p></div>
        <div class="field" style="margin-bottom:14px;"><label>${t('auth_email')}</label><input id="auth_email" type="email"></div>
        <button class="btn primary" style="width:100%;" id="forgotBtn">${t('auth_forgot_btn')}</button>
        <div class="auth-link" id="backToLogin">${t('auth_back_to_login')}</div>
      </div></div>`;
    document.getElementById('backToLogin').addEventListener('click', ()=>renderAuthScreen('login'));
    document.getElementById('forgotBtn').addEventListener('click', async ()=>{
      const email = document.getElementById('auth_email').value;
      try{ await sb.auth.resetPasswordForEmail(email); toast(t('auth_reset_sent')); renderAuthScreen('login'); }
      catch(e){ toast(t('auth_error_generic')); }
    });
    return;
  }

  main.innerHTML = `
    <div class="auth-wrap"><div class="card">
      <div class="onboard-header">
        <img src="${DIAMOND_LOGO}"><h1>DIAMONDMASS</h1>
        <p>${t('auth_tagline1')} ${t('auth_tagline2')}</p>
      </div>
      <div class="auth-tabs">
        <div class="auth-tab ${mode==='login'?'active':''}" data-mode="login">${t('auth_login_tab')}</div>
        <div class="auth-tab ${mode==='signup'?'active':''}" data-mode="signup">${t('auth_signup_tab')}</div>
      </div>
      <div class="field" style="margin-bottom:12px;"><label>${t('auth_email')}</label><input id="auth_email" type="email"></div>
      <div class="field" style="margin-bottom:12px;"><label>${t('auth_password')}</label><input id="auth_password" type="password"></div>
      ${mode==='signup' ? `<div class="field" style="margin-bottom:12px;"><label>${t('auth_confirmPassword')}</label><input id="auth_confirmPassword" type="password"></div>` : ''}
      <button class="btn primary" style="width:100%;" id="authSubmitBtn">${mode==='signup'?t('auth_signup_btn'):t('auth_login_btn')}</button>
      ${mode==='login' ? `<div class="auth-link" id="forgotLink">${t('auth_forgot')}</div>` : ''}
    </div></div>
  `;
  main.querySelectorAll('[data-mode]').forEach(el=>{
    el.addEventListener('click', ()=>renderAuthScreen(el.getAttribute('data-mode')));
  });
  if(mode==='login'){
    document.getElementById('forgotLink').addEventListener('click', ()=>renderAuthScreen('forgot'));
  }
  document.getElementById('authSubmitBtn').addEventListener('click', async ()=>{
    const email = document.getElementById('auth_email').value;
    const password = document.getElementById('auth_password').value;
    if(mode==='signup'){
      const confirm = document.getElementById('auth_confirmPassword').value;
      if(password !== confirm){ toast(t('auth_error_mismatch')); return; }
      try{
        const { error } = await sb.auth.signUp({ email, password });
        if(error) throw error;
        toast(t('auth_signup_success'));
        renderAuthScreen('login');
      }catch(e){ toast(e.message || t('auth_error_generic')); }
    } else {
      try{
        const { error } = await sb.auth.signInWithPassword({ email, password });
        if(error) throw error;
      }catch(e){ toast(e.message || t('auth_error_generic')); }
    }
  });
}

/* ============ WEEK MATH ============ */
function getCurrentWeekNumber(){
  if(!profile || !profile.start_date) return 1;
  const start = new Date(profile.start_date);
  const now = new Date();
  const diffDays = Math.floor((now - start) / (1000*60*60*24));
  let wk = Math.floor(diffDays/7) + 1;
  if(wk<1) wk=1; if(wk>16) wk=16;
  return wk;
}
function weekStatus(n){
  const cw = getCurrentWeekNumber();
  const data = checkins[n];
  if(n>cw && !(profile && profile.allow_future_checkins)) return 'locked';
  if(data && data.hasData){
    if(!data.photos || !(data.photos.front||data.photos.left||data.photos.right||data.photos.back)) return 'missing-photos';
    return 'completed';
  }
  if(n===cw) return 'current';
  return n<cw ? 'missing-photos' : 'upcoming';
}
function statusLabel(st){ return t('status_'+st.replace('-','')); }

