function renderNav(){
  const navList = canEdit ? NAV_FULL_KEYS : NAV_READONLY_KEYS;
  const bottomList = canEdit ? BOTTOM_NAV_FULL_KEYS : BOTTOM_NAV_READONLY_KEYS;
  document.getElementById('navItems').innerHTML = navList.map(n=>`<div class="nav-item" data-nav="${n.id}">${t(n.key)}</div>`).join('');
  document.getElementById('bottomNav').innerHTML = bottomList.map(n=>`<div class="bn-item" data-nav="${n.id}"><span class="bn-dot"></span>${t(n.key)}</div>`).join('');
  document.querySelectorAll('[data-nav]').forEach(el=>el.addEventListener('click', ()=>navigate(el.getAttribute('data-nav'))));
  if(coachMode) document.getElementById('sidebar').style.display='flex';
  setActiveNav(currentView);
  updateSidebarFooter();
}
function updateSidebarFooter(){
  const cw = getCurrentWeekNumber();
  document.getElementById('sidebarWeekPill').textContent = t('week_pill', cw);
  document.getElementById('sidebarGoalLine').textContent = profile ? t('goal_'+profile.goal) : '—';
  document.getElementById('logoutBtn').style.display = coachMode ? 'none' : 'block';
}
function setActiveNav(id){
  document.querySelectorAll('.nav-item').forEach(el=>el.classList.toggle('active', el.getAttribute('data-nav')===id));
  document.querySelectorAll('.bn-item').forEach(el=>el.classList.toggle('active', el.getAttribute('data-nav')===id));
}
function navigate(view){
  if(!canEdit && (view==='checkin' || view==='coachshare' || view==='profile')) view='dashboard';
  currentView = view;
  setActiveNav(view);
  if(view==='dashboard') renderDashboard();
  else if(view==='checkin') renderCheckin(getCurrentWeekNumber());
  else if(view==='photos') renderPhotosTimeline();
  else if(view==='compare') renderCompare();
  else if(view==='coachshare') renderCoachShare();
  else if(view==='profile') renderProfileSettings();
}

