  document.querySelectorAll('[data-week-tab]').forEach(el=>el.addEventListener('click', ()=>{
    const wk = Number(el.getAttribute('data-week-tab'));
    if(weekStatus(wk)==='locked'){ toast(t('lockedToast')); return; }
    renderCheckin(wk);
  }));
  document.querySelectorAll('[data-photo-action="upload"]').forEach(el=>el.addEventListener('click', ()=>startPhotoUpload(weekNum, el.getAttribute('data-view'))));
  document.querySelectorAll('[data-photo-action="delete"]').forEach(el=>el.addEventListener('click', ()=>deletePhoto(weekNum, el.getAttribute('data-view'))));
  document.getElementById('n_adherence').addEventListener('input', e=>{document.getElementById('n_adherence_v').textContent=e.target.value;});
  ['sleepQuality','energy','stress','recovery'].forEach(k=>{ const el=document.getElementById('rec_'+k); if(el) el.addEventListener('input', e=>{document.getElementById('rec_'+k+'_v').textContent=e.target.value;}); });
  TRAINING_DAY_KEYS.forEach(day=>document.getElementById('dw_'+day).addEventListener('input', updateWeightHint));
  renderTrainingDayTabs();
  renderTrainingDayPanel();
  document.getElementById('saveCheckinBtn').addEventListener('click', ()=>saveCheckin(weekNum));
