function updateWeightHint(){
  const dw={};
  TRAINING_DAY_KEYS.forEach(day=>{ const v=document.getElementById('dw_'+day).value; dw[day]=v===''?null:Number(v); });
  const avg = computeWeeklyAvg({dailyWeights:dw});
  const prevAvg = computeWeeklyAvg(checkins[currentCheckinWeek-1]);
  document.getElementById('weightAvgHint').innerHTML = `${t('avgLbl')} <b>${avg?fmt(avg)+' kg':'—'}</b> &nbsp;·&nbsp; ${t('changeFromLastWeek')} <b>${(avg&&prevAvg)?delta(avg,prevAvg)+' kg':'—'}</b>`;
}

/* ---- training log: 7-day tabs x 10 lifts ---- */
function trainingDayCount(dk){ return trainingDraft[dk].filter(s=>s.name||s.weight||s.reps).length; }
function renderTrainingDayTabs(){
  const wrap = document.getElementById('trainingDayTabs');
  if(!wrap) return;
  wrap.innerHTML = TRAINING_DAY_KEYS.map(dk=>{
    const cnt = trainingDayCount(dk);
    return `<div class="filter-tab ${dk===activeTrainingDay?'active':''}" data-training-day="${dk}">${t('day_'+dk)}${cnt?` · ${cnt}`:''}</div>`;
  }).join('');
  wrap.querySelectorAll('[data-training-day]').forEach(el=>{
    el.addEventListener('click', ()=>{
      flushActiveTrainingDay();
      activeTrainingDay = el.getAttribute('data-training-day');
      renderTrainingDayTabs();
      renderTrainingDayPanel();
    });
  });
}
function flushActiveTrainingDay(){
  const slots=[];
  for(let i=0;i<10;i++){
    const nameEl = document.getElementById('tlift_name_'+i);
    if(!nameEl){ slots.push(trainingDraft[activeTrainingDay][i]||{name:'',weight:'',reps:''}); continue; }
    slots.push({ name:nameEl.value||'', weight:document.getElementById('tlift_weight_'+i).value, reps:document.getElementById('tlift_reps_'+i).value });
  }
  trainingDraft[activeTrainingDay] = slots;
}
function renderTrainingDayPanel(){
  const panel = document.getElementById('trainingDayPanel');
  if(!panel) return;
  const slots = trainingDraft[activeTrainingDay];
  panel.innerHTML = slots.map((s,i)=>`
    <div class="field-row" style="grid-template-columns:2fr 1fr 1fr;">
      <div class="field"><label>${t('lift', i+1)}</label><input type="text" id="tlift_name_${i}" value="${s.name||''}" placeholder="${t('liftName')}"></div>
      <div class="field"><label>${t('liftWeight')}</label><input type="number" step="0.5" id="tlift_weight_${i}" value="${s.weight??''}"></div>
      <div class="field"><label>${t('liftReps')}</label><input type="number" id="tlift_reps_${i}" value="${s.reps??''}"></div>
    </div>`).join('');
  panel.querySelectorAll('input').forEach(el=>el.addEventListener('input', refreshTrainingDayCountBadge));
}
function refreshTrainingDayCountBadge(){
  const tab = document.querySelector(`[data-training-day="${activeTrainingDay}"]`);
  if(!tab) return;
  let cnt=0;
  for(let i=0;i<10;i++){
    const nameEl=document.getElementById('tlift_name_'+i), wEl=document.getElementById('tlift_weight_'+i), rEl=document.getElementById('tlift_reps_'+i);
    if((nameEl&&nameEl.value)||(wEl&&wEl.value)||(rEl&&rEl.value)) cnt++;
  }
  tab.textContent = t('day_'+activeTrainingDay) + (cnt?` · ${cnt}`:'');
}

/* ---- photos: Supabase Storage ---- */
async function hydratePhotoImages(container){
  const imgs = container.querySelectorAll('img[data-photo-path]');
  for(const img of imgs){
    const path = img.getAttribute('data-photo-path');
    if(!path) continue;
    if(photoUrlCache[path]){ img.src = photoUrlCache[path]; continue; }
    try{
      const { data, error } = await sb.storage.from(PHOTO_BUCKET).createSignedUrl(path, 3600);
      if(!error && data){ photoUrlCache[path] = data.signedUrl; img.src = data.signedUrl; }
    }catch(e){ /* ignore */ }
  }
}
function startPhotoUpload(weekNum, view){
  const input = document.getElementById('photoFileInput');
  input.onchange = async (e)=>{
    const file = e.target.files[0];
    if(!file) return;
    toast(t('toast_uploading'));
    try{
      const compressed = await compressImage(file, 1000, 0.82);
      const path = `${currentUser.id}/week-${String(weekNum).padStart(2,'0')}/${view}.jpg`;
      const { error: upErr } = await sb.storage.from(PHOTO_BUCKET).upload(path, compressed, { upsert:true, contentType:'image/jpeg' });
      if(upErr) throw upErr;
      delete photoUrlCache[path];
      const d = checkins[weekNum] || {week:weekNum, hasData:true};
      d.photos = d.photos || {};
      d.photos[view] = path;
      d.hasData = true;
      await saveCheckinData(weekNum, d);
      checkins[weekNum] = d;
      toast(t('toast_photo_saved'));
      renderCheckin(weekNum);
    }catch(err){ toast(t('toast_upload_failed')); }
  };
  input.value=''; input.click();
}
async function deletePhoto(weekNum, view){
  const d = checkins[weekNum];
  if(!d || !d.photos || !d.photos[view]) return;
  const path = d.photos[view];
  d.photos[view] = null;
  try{
    await saveCheckinData(weekNum, d);
    await sb.storage.from(PHOTO_BUCKET).remove([path]);
    delete photoUrlCache[path];
    checkins[weekNum]=d;
    toast(t('toast_photo_removed'));
    renderCheckin(weekNum);
  }catch(e){ toast(t('toast_delete_failed')); }
}
function compressImage(file, maxDim, quality){
  return new Promise((resolve,reject)=>{
    const img = new Image(); const reader = new FileReader();
    reader.onload = ()=>{ img.src = reader.result; };
    reader.onerror = reject;
    img.onload = ()=>{
      let w=img.width,h=img.height;
      if(w>h && w>maxDim){ h=Math.round(h*maxDim/w); w=maxDim; } else if(h>=w && h>maxDim){ w=Math.round(w*maxDim/h); h=maxDim; }
      const canvas=document.createElement('canvas'); canvas.width=w; canvas.height=h;
      canvas.getContext('2d').drawImage(img,0,0,w,h);
      canvas.toBlob(blob=>resolve(blob), 'image/jpeg', quality);
    };
    img.onerror=reject;
    reader.readAsDataURL(file);
  });
}

/* ---- save check-in row (upsert into checkins table) ---- */
async function saveCheckinData(weekNum, data){
  const { error } = await sb.from('checkins').upsert({ user_id: currentUser.id, week: weekNum, data, updated_at: new Date().toISOString() }, { onConflict:'user_id,week' });
  if(error) throw error;
}
function numOrNull(id){ const v=document.getElementById(id).value; return v===''?null:Number(v); }

async function saveCheckin(weekNum){
  const dw={};
  TRAINING_DAY_KEYS.forEach(day=>{ const v=document.getElementById('dw_'+day).value; dw[day]=v===''?null:Number(v); });
  flushActiveTrainingDay();
  const trainingDays={};
  TRAINING_DAY_KEYS.forEach(dk=>{
    trainingDays[dk] = trainingDraft[dk].filter(s=>s.name||s.weight||s.reps).map(s=>({name:s.name||'', weight:s.weight?Number(s.weight):null, reps:s.reps?Number(s.reps):null}));
  });
  const existing = checkins[weekNum] || {};
  const data = {
    week: weekNum, hasData:true, photos: existing.photos || {}, dailyWeights: dw,
    measurements: { waist:numOrNull('m_waist'), chest:numOrNull('m_chest'), armL:numOrNull('m_armL'), armR:numOrNull('m_armR'), thighL:numOrNull('m_thighL'), thighR:numOrNull('m_thighR'), hip:numOrNull('m_hip') },
    nutrition: { avgCalories:numOrNull('n_cal'), avgProtein:numOrNull('n_protein'), adherenceDays:Number(document.getElementById('n_adherence').value) },
    training: { planned:numOrNull('t_planned'), completed:numOrNull('t_completed'), days:trainingDays },
    activity: { avgSteps:numOrNull('act_steps'), cardioMinutes:numOrNull('act_cardioMin'), cardioSessions:numOrNull('act_cardioSessions') },
    recovery: { sleepHours:numOrNull('rec_sleepHours'), sleepQuality:Number(document.getElementById('rec_sleepQuality').value), energy:Number(document.getElementById('rec_energy').value), stress:Number(document.getElementById('rec_stress').value), recovery:Number(document.getElementById('rec_recovery').value) },
    reflection: { wentWell:document.getElementById('ref_well').value, difficult:document.getElementById('ref_difficult').value, improve:document.getElementById('ref_improve').value, noteToCoach:document.getElementById('ref_coach').value },
    updatedAt: new Date().toISOString(),
  };
  try{ await saveCheckinData(weekNum, data); checkins[weekNum]=data; toast(t('toast_week_saved', weekNum)); }
  catch(e){ toast(t('toast_save_failed')); }
}

