/* ============ COMPARE ============ */
function renderCompare(){
  document.getElementById('main').innerHTML = `
    ${!canEdit?`<div class="readonly-banner">${t('coach_readonly')}</div>`:''}
    <div class="page-title">${t('compare_title')}</div>
    <div class="page-sub">${t('compare_sub')}</div>
    <div class="grid cols-3" style="margin-bottom:16px;align-items:end;">
      <div class="field"><label>${t('fromWeek')}</label><select id="cmp_from">${weekOptions(compareState.from)}</select></div>
      <div class="field"><label>${t('toWeek')}</label><select id="cmp_to">${weekOptions(compareState.to)}</select></div>
      <div class="field"><label>${t('view')}</label><select id="cmp_view">${['front','left','right','back'].map(v=>`<option value="${v}" ${v===compareState.view?'selected':''}>${t('ph_'+v)}</option>`).join('')}</select></div>
    </div>
    <label style="font-size:12px;display:flex;align-items:center;gap:6px;margin-bottom:16px;"><input type="checkbox" id="cmp_hideNumbers" ${compareState.hideNumbers?'checked':''}> ${t('hideNumbers')}</label>
    <div id="compareOutput"></div>
  `;
  ['cmp_from','cmp_to','cmp_view'].forEach(id=>document.getElementById(id).addEventListener('change', ()=>{
    compareState.from=Number(document.getElementById('cmp_from').value);
    compareState.to=Number(document.getElementById('cmp_to').value);
    compareState.view=document.getElementById('cmp_view').value;
    renderCompareOutput();
  }));
  document.getElementById('cmp_hideNumbers').addEventListener('change', e=>{ compareState.hideNumbers=e.target.checked; renderCompareOutput(); });
  renderCompareOutput();
}
function weekOptions(sel){ let out=''; for(let i=1;i<=16;i++) out+=`<option value="${i}" ${i===sel?'selected':''}>${t('weekOpt', i)}</option>`; return out; }
function renderCompareOutput(){
  const from = checkins[compareState.from]||{}; const to = checkins[compareState.to]||{};
  const pathFrom = from.photos?from.photos[compareState.view]:null;
  const pathTo = to.photos?to.photos[compareState.view]:null;
  const wFrom = computeWeeklyAvg(from), wTo = computeWeeklyAvg(to);
  const waistFrom = from.measurements?from.measurements.waist:null;
  const waistTo = to.measurements?to.measurements.waist:null;
  const el = document.getElementById('compareOutput');
  el.innerHTML = `
    <div class="grid cols-2" style="margin-bottom:16px;">
      <div style="text-align:center;"><div style="font-size:11px;font-weight:700;color:var(--muted);margin-bottom:6px;">${t('weekLbl', compareState.from)}</div>
        ${pathFrom?`<img data-photo-path="${pathFrom}" style="width:100%;border-radius:12px;border:1px solid var(--border);">`:`<div style="aspect-ratio:3/4;background:var(--cream-soft);border-radius:12px;border:1px dashed var(--border);"></div>`}</div>
      <div style="text-align:center;"><div style="font-size:11px;font-weight:700;color:var(--muted);margin-bottom:6px;">${t('weekLbl', compareState.to)}</div>
        ${pathTo?`<img data-photo-path="${pathTo}" style="width:100%;border-radius:12px;border:1px solid var(--border);">`:`<div style="aspect-ratio:3/4;background:var(--cream-soft);border-radius:12px;border:1px dashed var(--border);"></div>`}</div>
    </div>
    ${!compareState.hideNumbers?`
    <div class="grid cols-2">
      <div class="card stat-card"><div class="stat-label">${t('weightLbl')}</div><div class="stat-value" style="font-size:18px;">${fmt(wFrom)} → ${fmt(wTo)} KG</div></div>
      <div class="card stat-card"><div class="stat-label">${t('waistLbl')}</div><div class="stat-value" style="font-size:18px;">${fmt(waistFrom)} → ${fmt(waistTo)} CM</div></div>
    </div>`:''}
  `;
  hydratePhotoImages(el);
}

/* ============ COACH SHARE ============ */
function renderCoachShare(){
  const active = !!profile.coach_share_active;
  const link = `${window.location.origin}${window.location.pathname}?coach=${profile.coach_token}`;
  document.getElementById('main').innerHTML = `
    <div class="page-title">${t('coachshare_title')}</div>
    <div class="page-sub">${t('coachshare_sub')}</div>
    <div class="card" style="margin-bottom:20px;">
      <p style="font-size:13px;line-height:1.8;margin-bottom:14px;">${t('coachshare_p1')}</p>
      <p style="font-size:13px;line-height:1.8;color:var(--muted);margin-bottom:16px;">${t('coachshare_p2')}</p>
      <div class="hint-box" style="display:flex;align-items:center;justify-content:space-between;gap:10px;">
        <span>${active?t('coachLinkActive'):t('coachLinkInactive')}</span>
        <button class="btn ${active?'secondary':'primary'} small" id="toggleCoachLink">${active?t('coachLinkToggleOff'):t('coachLinkToggleOn')}</button>
      </div>
      ${active?`
      <div class="field" style="margin-top:14px;"><label>LINK</label><input type="text" id="coachLinkInput" value="${link}" readonly></div>
      <div style="display:flex; gap:8px; margin-top:10px; flex-wrap:wrap;">
        <button class="btn secondary small" id="copyLinkBtn">${t('copyLink')}</button>
        <button class="btn secondary small" id="regenLinkBtn">${t('regenerateLink')}</button>
      </div>` : ''}
    </div>
    <button class="btn primary" id="downloadCoachReport">${t('downloadCoachReport')}</button>
    <div style="height:30px;"></div>
    <h2 class="section-title">${t('shareProgressCard')}</h2>
    <p style="font-size:12.5px;color:var(--muted);margin-bottom:14px;">${t('shareProgressCardSub')}</p>
    <div class="field-row" style="max-width:400px;">
      <label style="font-size:12px;display:flex;align-items:center;gap:6px;"><input type="checkbox" id="share_showWeight" checked> ${t('showWeight')}</label>
      <label style="font-size:12px;display:flex;align-items:center;gap:6px;"><input type="checkbox" id="share_showWaist" checked> ${t('showWaist')}</label>
    </div>
    <div class="share-card-canvas-wrap"><canvas id="shareCanvas" width="360" height="640"></canvas></div>
    <button class="btn primary" id="downloadShareCard">${t('downloadProgressCard')}</button>
  `;
  drawShareCard();
  document.getElementById('share_showWeight').addEventListener('change', drawShareCard);
  document.getElementById('share_showWaist').addEventListener('change', drawShareCard);
  document.getElementById('downloadShareCard').addEventListener('click', ()=>downloadCanvas('shareCanvas','diamondmass-progress.png'));
  document.getElementById('downloadCoachReport').addEventListener('click', downloadCoachReport);
  document.getElementById('toggleCoachLink').addEventListener('click', async ()=>{
    const newActive = !active;
    await sb.from('profiles').update({ coach_share_active: newActive }).eq('id', currentUser.id);
    profile.coach_share_active = newActive;
    renderCoachShare();
  });
  if(active){
    document.getElementById('copyLinkBtn').addEventListener('click', ()=>{
      navigator.clipboard.writeText(link).then(()=>toast(t('toast_link_copied')));
    });
    document.getElementById('regenLinkBtn').addEventListener('click', async ()=>{
      const newToken = crypto.randomUUID();
      await sb.from('profiles').update({ coach_token:newToken }).eq('id', currentUser.id);
      profile.coach_token = newToken;
      renderCoachShare();
      toast(t('toast_saved'));
    });
  }
}
function drawShareCard(){
  const canvas = document.getElementById('shareCanvas'); const ctx = canvas.getContext('2d');
  const cw = getCurrentWeekNumber();
  ctx.fillStyle='#F7F3E8'; ctx.fillRect(0,0,360,640);
  ctx.fillStyle='#33271E'; ctx.font='900 22px Inter, sans-serif'; ctx.textAlign='center';
  ctx.fillText('DIAMONDMASS', 180, 90);
  ctx.font='700 14px Inter, sans-serif'; ctx.fillStyle='#6B5138';
  ctx.fillText(t('week_pill', cw), 180, 118);
  const weightSeries = getSeriesForWeeks('weight'); const waistSeries = getSeriesForWeeks('waist');
  const startW = profile.start_weight||firstNonNull(weightSeries); const curW = lastNonNull(weightSeries)||startW;
  const startWaist = profile.start_waist||firstNonNull(waistSeries); const curWaist = lastNonNull(waistSeries)||startWaist;
  let y=280;
  if(document.getElementById('share_showWeight').checked){
    ctx.fillStyle='#1F1C18'; ctx.font='900 40px Inter, sans-serif'; ctx.fillText(delta(curW,startW)+' KG', 180, y);
    ctx.font='700 12px Inter, sans-serif'; ctx.fillStyle='#756A5D'; ctx.fillText(t('weekChangeUnit'), 180, y+24); y+=90;
  }
  if(document.getElementById('share_showWaist').checked){
    ctx.fillStyle='#1F1C18'; ctx.font='900 40px Inter, sans-serif'; ctx.fillText(delta(curWaist,startWaist)+' CM', 180, y);
    ctx.font='700 12px Inter, sans-serif'; ctx.fillStyle='#756A5D'; ctx.fillText(t('waistChangeUnit'), 180, y+24);
  }
  ctx.font='700 11px Inter, sans-serif'; ctx.fillStyle='#D8C6A3'; ctx.fillText(t('transformationTag'), 180, 600);
}
function downloadCanvas(canvasId, filename){
  const canvas = document.getElementById(canvasId);
  canvas.toBlob((blob)=>{
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href=url; a.download=filename; a.click();
    URL.revokeObjectURL(url); toast(t('toast_saved'));
  }, 'image/png');
}
function downloadCoachReport(){
  const cw = getCurrentWeekNumber(); const cs = computeConsistency();
  const weightSeries = getSeriesForWeeks('weight'); const waistSeries = getSeriesForWeeks('waist');
  const canvas = document.createElement('canvas'); canvas.width=800; canvas.height=1000;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle='#F7F3E8'; ctx.fillRect(0,0,800,1000);
  ctx.fillStyle='#33271E'; ctx.font='900 30px Inter, sans-serif'; ctx.textAlign='left';
  ctx.fillText(t('coachReportTitle'), 40, 60);
  ctx.font='700 16px Inter, sans-serif'; ctx.fillStyle='#6B5138';
  ctx.fillText((profile.name||'—')+' · '+t('week_pill', cw)+' · '+t('goal_'+profile.goal), 40, 90);
  const rows = [
    [t('cr_startWeight'), fmt(profile.start_weight)+' kg'], [t('cr_currentWeight'), fmt(lastNonNull(weightSeries))+' kg'],
    [t('cr_startWaist'), fmt(profile.start_waist)+' cm'], [t('cr_currentWaist'), fmt(lastNonNull(waistSeries))+' cm'],
    [t('cr_consistency'), cs.overall+'%'], [t('cr_training'), cs.training+'%'],
    [t('cr_nutrition'), cs.nutrition+'%'], [t('cr_checkin'), cs.checkin+'%'],
  ];
  let y=150; ctx.font='600 16px Inter, sans-serif'; ctx.fillStyle='#1F1C18';
  rows.forEach(r=>{ ctx.fillStyle='#756A5D'; ctx.fillText(r[0], 40, y); ctx.fillStyle='#1F1C18'; ctx.fillText(String(r[1]), 420, y); y+=36; });
  ctx.font='700 14px Inter, sans-serif'; ctx.fillStyle='#33271E'; ctx.fillText(t('cr_latestNote'), 40, y+20);
  ctx.font='400 13px Inter, sans-serif'; ctx.fillStyle='#1F1C18';
  const latestWeek = Object.keys(checkins).map(Number).sort((a,b)=>b-a)[0];
  const note = latestWeek && checkins[latestWeek].reflection ? (checkins[latestWeek].reflection.noteToCoach||'—') : '—';
  wrapText(ctx, note, 40, y+46, 720, 18);
  canvas.toBlob((blob)=>{
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href=url; a.download='diamondmass-coach-report.png'; a.click();
    URL.revokeObjectURL(url); toast(t('toast_saved'));
  }, 'image/png');
}
function wrapText(ctx, text, x, y, maxWidth, lineHeight){
  const words = (text||'').split(' '); let line='';
  for(let n=0;n<words.length;n++){
    const testLine = line+words[n]+' ';
    if(ctx.measureText(testLine).width>maxWidth && n>0){ ctx.fillText(line,x,y); line=words[n]+' '; y+=lineHeight; } else line=testLine;
  }
  ctx.fillText(line, x, y);
}

/* ============ PROFILE SETTINGS ============ */
function renderProfileSettings(){
  document.getElementById('main').innerHTML = `
    <div class="page-title">${t('profile_title')}</div>
    <div class="hint-box" style="display:flex;align-items:center;justify-content:space-between;gap:12px;">
      <span>${t('ob_sub_edit')}</span>
      <button class="btn secondary small" id="openFullOnboarding">${t('ob_title_edit')}</button>
    </div>
    <div class="form-section">
      <div class="field-row">
        <div class="field"><label>${t('p_name')}</label><input id="p_name" value="${profile.name||''}"></div>
        <div class="field"><label>${t('p_goal')}</label><select id="p_goal"><option value="cutting" ${profile.goal==='cutting'?'selected':''}>${t('goal_cutting')}</option><option value="bulking" ${profile.goal==='bulking'?'selected':''}>${t('goal_bulking')}</option></select></div>
      </div>
      <div class="field-row">
        <div class="field"><label>${t('p_targetWeight')}</label><input type="number" id="p_targetWeight" value="${profile.target_weight??''}"></div>
        <div class="field"><label>${t('p_trainingDays')}</label><input type="number" id="p_trainingDays" value="${profile.training_days??''}"></div>
      </div>
      <div class="field-row">
        <div class="field"><label>${t('p_calorieTarget')}</label><input type="number" id="p_calorieTarget" value="${profile.calorie_target??''}"></div>
        <div class="field"><label>${t('p_proteinTarget')}</label><input type="number" id="p_proteinTarget" value="${profile.protein_target??''}"></div>
      </div>
      <div class="field-row">
        <div class="field"><label>${t('p_stepsTarget')}</label><input type="number" id="p_stepsTarget" value="${profile.steps_target??''}"></div>
        <div class="field"><label>${t('p_cardioTarget')}</label><input type="number" id="p_cardioTarget" value="${profile.cardio_target??''}"></div>
      </div>
      <label style="font-size:12px;display:flex;align-items:center;gap:8px;margin-top:6px;"><input type="checkbox" id="p_allowFuture" ${profile.allow_future_checkins?'checked':''}> ${t('allowFuture')}</label>
    </div>
    <button class="btn primary" id="saveProfileBtn">${t('saveProfile')}</button>
  `;
  document.getElementById('openFullOnboarding').addEventListener('click', ()=>renderOnboarding(true));
  document.getElementById('saveProfileBtn').addEventListener('click', async ()=>{
    profile.name = document.getElementById('p_name').value;
    profile.goal = document.getElementById('p_goal').value;
    profile.target_weight = numOrNull('p_targetWeight');
    profile.training_days = numOrNull('p_trainingDays');
    profile.calorie_target = numOrNull('p_calorieTarget');
    profile.protein_target = numOrNull('p_proteinTarget');
    profile.steps_target = numOrNull('p_stepsTarget');
    profile.cardio_target = numOrNull('p_cardioTarget');
    profile.allow_future_checkins = document.getElementById('p_allowFuture').checked;
    try{
      const { error } = await sb.from('profiles').update({
        name:profile.name, goal:profile.goal, target_weight:profile.target_weight, training_days:profile.training_days,
        calorie_target:profile.calorie_target, protein_target:profile.protein_target, steps_target:profile.steps_target,
        cardio_target:profile.cardio_target, allow_future_checkins:profile.allow_future_checkins,
      }).eq('id', currentUser.id);
      if(error) throw error;
      toast(t('toast_profile_saved'));
      renderNav();
    }catch(e){ toast(t('toast_save_failed')); }
  });
}

init();
